const INDEX_HTML="<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"description\" content=\"面向北美求职市场的简历修改入口。\">\n  <title>安妮老师的简历修改小工具</title>\n  <link rel=\"icon\" type=\"image/svg+xml\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%230d2333'/%3E%3Cpath d='M18 14h28v36H18z' fill='none' stroke='%23f4c95d' stroke-width='4'/%3E%3Cpath d='M25 24h14M25 32h14M25 40h9' stroke='%23f4c95d' stroke-width='3' stroke-linecap='round'/%3E%3C/svg%3E\">\n  <style>\n    :root{--ink:#102433;--muted:#5d6d76;--line:#d7e1e4;--paper:#fbfcfa;--cream:#f2f0e9;--gold:#e7b84b;--teal:#0e6f70;--teal-dark:#075051;--danger:#a43c36;--shadow:0 18px 50px rgba(16,36,51,.10)}\n    *{box-sizing:border-box} body{margin:0;background:var(--cream);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif;font-size:16px;line-height:1.5}\n    .shell{max-width:1120px;margin:0 auto;padding:28px 22px 56px}.brand{display:flex;align-items:center;justify-content:space-between;margin-bottom:42px}.mark{display:flex;align-items:center;gap:12px;font-weight:750;letter-spacing:.01em}.mark-dot{width:34px;height:34px;border-radius:10px;background:var(--ink);display:grid;place-items:center;color:var(--gold);font-weight:850}.avatar{width:42px;height:42px;border-radius:50%;object-fit:cover;display:block;border:2px solid rgba(16,36,51,.12);box-shadow:0 4px 12px rgba(16,36,51,.12)}.status{font-size:13px;color:var(--muted);display:flex;gap:8px;align-items:center}.status i{width:8px;height:8px;border-radius:50%;background:#3d9c72;display:block}\n    .hero{max-width:780px;margin-bottom:28px}.eyebrow{color:var(--teal);font-size:13px;font-weight:800;letter-spacing:.15em;text-transform:uppercase}.hero h1{font-family:Georgia,serif;font-size:clamp(40px,6vw,72px);line-height:1.02;letter-spacing:-.045em;margin:13px 0 18px;font-weight:500}.hero p{font-size:18px;color:var(--muted);max-width:660px;margin:0}\n    .grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(280px,.7fr);gap:22px;align-items:start}.card{background:var(--paper);border:1px solid rgba(16,36,51,.08);border-radius:22px;box-shadow:var(--shadow);padding:27px}.card h2{font-size:20px;margin:0 0 6px;letter-spacing:-.02em}.card .intro{margin:0 0 22px;color:var(--muted);font-size:14px}.step{display:flex;gap:12px;margin:0 0 22px}.step-num{flex:0 0 28px;height:28px;border-radius:50%;background:var(--ink);color:white;display:grid;place-items:center;font-size:13px;font-weight:800}.step-body{flex:1}.step-body label{display:block;font-weight:750;margin:0 0 8px}.hint{font-size:13px;color:var(--muted);margin-top:6px}.upload{border:1.5px dashed #aebfc2;border-radius:16px;padding:22px;background:#f6faf8;display:flex;align-items:center;gap:15px;cursor:pointer;transition:.2s}.upload:hover,.upload:focus-within{border-color:var(--teal);background:#eef8f5}.upload strong{display:block}.upload small{color:var(--muted)}.upload input{position:absolute;opacity:0;width:1px;height:1px}.file-name{margin-top:8px;color:var(--teal-dark);font-size:14px;min-height:21px}.field{display:grid;gap:7px;margin-top:14px}.field label{font-weight:700;font-size:14px}.field input,.field select,.field textarea{font:inherit;border:1px solid var(--line);border-radius:11px;background:white;padding:12px 13px;color:var(--ink);outline:none}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--teal);box-shadow:0 0 0 3px rgba(14,111,112,.12)}.field textarea{resize:vertical;min-height:84px}.chips{display:flex;flex-wrap:wrap;gap:8px}.chip{border:1px solid var(--line);background:white;border-radius:999px;padding:8px 12px;font-size:13px;cursor:pointer}.chip[aria-pressed=true]{background:#dff1ea;border-color:#73aa9a;color:var(--teal-dark);font-weight:700}.actions{display:flex;align-items:center;gap:13px;margin-top:25px}.primary{border:0;border-radius:11px;background:var(--teal);color:white;padding:13px 17px;font:inherit;font-weight:800;cursor:pointer}.primary:hover{background:var(--teal-dark)}.primary:disabled{opacity:.45;cursor:not-allowed}.privacy{font-size:12px;color:var(--muted);margin:13px 0 0}.side{display:grid;gap:22px}.side .card{box-shadow:none}.side h3{font-size:15px;margin:0 0 12px}.principles{display:grid;gap:12px}.principle{display:flex;gap:10px}.principle b{font-size:14px}.principle span{display:block;color:var(--muted);font-size:13px}.tick{width:22px;height:22px;border-radius:7px;background:#dff1ea;color:var(--teal-dark);display:grid;place-items:center;font-weight:900;flex:0 0 22px}.code-note{border-left:3px solid var(--gold);padding-left:14px;color:var(--muted);font-size:14px}.result{display:none;margin-top:22px;border-radius:16px;background:#e9f5ee;border:1px solid #acd4bf;padding:16px}.result.show{display:block}.result strong{display:block;color:#1b6241}.feedback{white-space:pre-wrap;display:block;margin-top:10px;color:var(--ink);font-size:14px;line-height:1.65}.contact-card img{width:100%;display:block;border-radius:14px;margin-top:14px}.projects-card ol{margin:0;padding-left:22px;color:var(--muted);font-size:14px}.projects-card li{padding:5px 0}.projects-card li::marker{color:var(--teal);font-weight:700}.footer{display:flex;justify-content:flex-end;gap:15px;color:var(--muted);font-size:12px;margin-top:24px;padding:0 4px}.error{color:var(--danger);font-size:13px;margin-top:8px;min-height:18px}\n    @media (max-width:820px){.grid{grid-template-columns:1fr}.side{grid-template-columns:1fr 1fr}.brand{margin-bottom:30px}.hero h1{font-size:48px}}\n    @media (max-width:560px){.shell{padding:20px 14px 38px}.card{padding:21px;border-radius:18px}.side{grid-template-columns:1fr}.footer{flex-direction:column}.actions{align-items:stretch;flex-direction:column}.primary{width:100%}}\n  </style>\n</head>\n<body>\n  <main class=\"shell\">\n    <header class=\"brand\"><div class=\"mark\"><span class=\"mark-dot\">R</span><span>安妮老师的简历小工具</span><img class=\"avatar\" src=\"data:image/png;base64,\" alt=\"安妮老师头像\"></div><div class=\"status\"><i></i>北美求职方向</div></header>\n    <section class=\"hero\"><div class=\"eyebrow\">简历修改入口</div><h1>让简历更清楚、更匹配、更可信。</h1></section>\n    <div class=\"grid\">\n      <section class=\"card\">\n        <h2>开始修改简历</h2><p class=\"intro\">回答几个问题，让修改有明确的目标和依据。</p>\n        <form id=\"intakeForm\">\n          <div class=\"step\"><span class=\"step-num\">1</span><div class=\"step-body\"><label for=\"resumeFile\">上传简历</label><label class=\"upload\" for=\"resumeFile\"><span style=\"font-size:25px\">↥</span><span><strong>选择 PDF 或 Word 文件</strong><small>上传当前版本即可</small></span><input id=\"resumeFile\" type=\"file\" accept=\".pdf,.doc,.docx\"></label><div id=\"fileName\" class=\"file-name\"></div></div></div>\n          <div class=\"step\"><span class=\"step-num\">2</span><div class=\"step-body\"><label for=\"code\">输入授权码</label><input id=\"code\" required autocomplete=\"off\" placeholder=\"示例：RA-ALPHA-05\"><div class=\"hint\">每个授权码由我们设定 2–10 次使用额度，提交前会显示剩余次数。</div><div id=\"codeError\" class=\"error\"></div></div></div>\n          <div class=\"step\"><span class=\"step-num\">3</span><div class=\"step-body\"><label for=\"role\">你准备申请什么方向？</label><select id=\"role\" required><option value=\"\">请选择目标方向</option><option>医疗 / 生命科学</option><option>金融 / 风险 / 量化分析</option><option>科技 / 数据 / 产品</option><option>咨询 / 运营</option><option>学术 / 研究</option><option>其他或仍在探索</option></select><div class=\"field\"><label for=\"level\">职业阶段</label><select id=\"level\"><option>应届 / 职业早期</option><option>中期职业阶段</option><option>资深 / 负责人</option><option>高管</option><option>学术 / 研究</option></select></div><div class=\"field\"><label>这次修改最希望优先解决什么？</label><div class=\"chips\" id=\"chips\"><button type=\"button\" class=\"chip\" aria-pressed=\"false\">职业定位</button><button type=\"button\" class=\"chip\" aria-pressed=\"false\">ATS 可读性</button><button type=\"button\" class=\"chip\" aria-pressed=\"false\">成果型 bullet</button><button type=\"button\" class=\"chip\" aria-pressed=\"false\">一页结构</button></div></div><div class=\"field\"><label for=\"notes\">有哪些内容需要保留或避免？</label><textarea id=\"notes\" placeholder=\"例如：保留现有模板；不要加入经历无法支持的表述。\"></textarea></div></div></div>\n          <div class=\"actions\"><button class=\"primary\" type=\"submit\" id=\"submitBtn\" disabled>提交修改请求</button><span class=\"hint\">提交后会生成针对性的修改任务。</span></div><p class=\"privacy\">文件仅用于本次修改请求。请不要上传护照、社保号码或其他敏感身份材料。</p>\n        </form><div id=\"result\" class=\"result\"><strong id=\"resultTitle\">分析结果</strong><span id=\"resultText\">正在准备分析。</span><span id=\"feedback\" class=\"feedback\"></span></div>\n      </section>\n      <aside class=\"side\">\n        <section class=\"card\"><h3>授权码控制</h3><p class=\"code-note\">授权码由我们生成，并设定 2–10 次固定额度。每次真实分析会在服务器端扣除一次。</p><p class=\"hint\" style=\"margin-bottom:0\">如果授权码无效，请联系安妮。</p></section><section class=\"card contact-card\"><img src=\"data:image/jpeg;base64,\" alt=\"在小红书找到安妮\"></section><section class=\"card projects-card\"><h3>咨询项目</h3><ol><li>北美简历深度修改</li><li>Resume + Cover Letter 求职材料套装</li><li>LinkedIn 个人主页优化</li><li>求职定位与岗位匹配咨询</li><li>面试准备与模拟</li></ol></section>\n      </aside>\n    </div>\n    <footer class=\"footer\"></footer>\n  </main>\n  <script src=\"https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs\" type=\"module\"></script>\n  <script>\n    const code=document.querySelector('#code'), file=document.querySelector('#resumeFile'), nameEl=document.querySelector('#fileName'), err=document.querySelector('#codeError'), submit=document.querySelector('#submitBtn'), form=document.querySelector('#intakeForm'), result=document.querySelector('#result'), resultText=document.querySelector('#resultText'), feedback=document.querySelector('#feedback');\n    file.addEventListener('change',()=>{nameEl.textContent=file.files[0]?file.files[0].name:''; refresh()});\n    document.querySelectorAll('.chip').forEach(c=>c.addEventListener('click',()=>c.setAttribute('aria-pressed',c.getAttribute('aria-pressed')!=='true')));\n    async function extractText(f){\n      const n=f.name.toLowerCase();\n      if(n.endsWith('.pdf')){const pdfjs=await import('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.4.168/pdf.min.mjs'); const pdf=await pdfjs.getDocument({data:await f.arrayBuffer()}).promise; let out=''; for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i); const c=await page.getTextContent(); out+=c.items.map(x=>x.str).join(' ')+'\\n';} return out;}\n      if(n.endsWith('.docx')){const mammoth=await import('https://cdn.jsdelivr.net/npm/mammoth@1.8.0/+esm'); const r=await mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()}); return r.value;}\n      if(n.endsWith('.txt')) return f.text();\n      throw new Error('目前支持 PDF 和 Word（.docx）文件。');\n    }\n    function refresh(){const valid=code.value.trim().toUpperCase()==='RA-ALPHA-05'; err.textContent=code.value&&!valid?'请检查授权码后重试。':(valid?'授权码有效 · 服务器分析会扣除一次。':''); submit.disabled=!(file.files[0]&&valid)}\n    code.addEventListener('input',refresh);\n    form.addEventListener('submit',async e=>{e.preventDefault(); refresh(); if(submit.disabled)return; submit.disabled=true; result.classList.add('show'); resultText.textContent='正在解析简历并调用 AI 分析，请稍候。'; feedback.textContent=''; try{const text=await extractText(file.files[0]); const selected=[...document.querySelectorAll('.chip[aria-pressed=true]')].map(x=>x.textContent).join('、'); const res=await fetch('/api/analyze',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({resumeText:text,filename:file.files[0].name,role:document.querySelector('#role').value,level:document.querySelector('#level').value,priorities:selected,notes:document.querySelector('#notes').value,code:code.value.trim().toUpperCase()})}); const data=await res.json(); if(!res.ok)throw new Error(data.error||'分析失败'); resultText.textContent=`分析完成。该授权码剩余 ${data.remaining} 次。`; feedback.textContent=data.feedback||'未返回分析内容。'; }catch(ex){resultText.textContent='分析未完成'; feedback.textContent=ex.message||'请联系安妮。';}finally{refresh()}});\n  </script>\n</body>\n</html>\n";
let usage={}; // ponytail: process-local counter; move to D1 before multi-instance billing.
const CODES={"RA-ALPHA-05":5,"RA-BETA-02":2,"RA-GAMMA-10":10};
const out=(d,s=200)=>new Response(JSON.stringify(d),{status:s,headers:{"content-type":"application/json; charset=utf-8","access-control-allow-origin":"*"}});
async function analyze(req,env){const b=await req.json(),code=String(b.code||'').toUpperCase(),max=CODES[code]||0,used=usage[code]||0;if(!max)return out({error:'授权码无效，请联系安妮。'},401);if(used>=max)return out({error:'该授权码已无剩余次数。'},429);const resume=String(b.resumeText||'').trim();if(resume.length<40)return out({error:'未能读取到足够的简历文字，请上传可复制文字的 PDF/Word 文件。'},400);const isDeep=!!(env.DEEPSEEK_API_KEY&&env.DEEPSEEK_MODEL),key=isDeep?env.DEEPSEEK_API_KEY:env.ARK_API_KEY,model=isDeep?env.DEEPSEEK_MODEL:env.ARK_MODEL,endpoint=isDeep?((env.DEEPSEEK_BASE_URL||'https://api.deepseek.com')+'/chat/completions'):'https://ark.cn-beijing.volces.com/api/v3/chat/completions';if(!key||!model)return out({error:'分析服务尚未配置，请联系安妮。'},503);const prompt=`你是北美求职简历顾问。请根据下面的简历原文和求职背景，给出真实、可执行的修改结果。严格保留事实，不编造经历、数字、雇主或学历。输出中文，包含：1) 一句话职业定位；2) 最需要修改的5项；3) 可直接替换的Summary；4) 3条示范性经历bullet（只基于原文事实）；5) 版式和ATS可读性建议；6) 需要向候选人确认的信息。目标方向：${b.role||'未填写'}；职业阶段：${b.level||'未填写'}；优先项：${b.priorities||'未填写'}；备注：${b.notes||'无'}。简历原文：\n${resume.slice(0,30000)}`;
const up=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${key}`},body:JSON.stringify({model,messages:[{role:'user',content:prompt}],temperature:0.2,thinking:{type:'disabled'},max_tokens:3000})});const data=await up.json();if(!up.ok)return out({error:(data.error&&data.error.message)||'AI 分析服务暂时不可用。'},502);usage[code]=used+1;return out({remaining:max-usage[code],feedback:data.choices?.[0]?.message?.content||'模型未返回文本。'})}
export default{async fetch(req,env){const u=new URL(req.url);if(u.pathname==='/api/analyze'&&req.method==='POST'){try{return await analyze(req,env)}catch(e){return out({error:'分析请求处理失败，请联系安妮。'},500)}}if(u.pathname==='/'||u.pathname==='/index.html')return new Response(INDEX_HTML,{headers:{'content-type':'text/html; charset=utf-8'}});return new Response('Not found',{status:404})}};
